Color3=Color3.fromRGB(225,29,61)U.BorderSizePixel=0 U.Text="GET NEW KEY"U.Font=Enum.Font.GothamBold U.TextSize=14 U.TextColor3=Color3.fromRGB(255,255,255)U.AutoButtonColor=true local H=Instance.new("UICorner",U)H.CornerRadius=UDim.new(0,9)local C=Instance.new("TextLabel",r)C.Size=UDim2.new(1,-40,0,16)C.Position=UDim2.new(0,20,1,-24)C.BackgroundTransparency=1 C.Text="link copied - re-execute Silence with the new key"C.Font=Enum.Font.Gotham C.TextSize=10 C.TextColor3=Color3.fromRGB(120,120,130)C.TextTransparency=1 local J=Instance.new("TextButton",r)J.Size=UDim2.new(0,26,0,26)J.Position=UDim2.new(1,-32,0,8)J.BackgroundTransparency=1 J.Text="X"J.Font=Enum.Font.GothamBold J.TextSize=14 J.TextColor3=Color3.fromRGB(140,140,150)U.MouseButton1Click:Connect(function()local x=false pcall(function()if setclipboard then setclipboard(L)x=true elseif toclipboard then toclipboard(L)x=true end end)U.Text=x and"LINK COPIED"or"SELECT THE LINK ABOVE & COPY"C.TextTransparency=x and 0 or 1 end)J.MouseButton1Click:Connect(function()pcall(function()Y:Destroy()end)end)end while true do task.wait(20)if Q and Q.__SilenceAdminPanel~=x then return end local Y=(not S)and(E>0 and os.time()>=E)if Y then f=os.clock()if y()then Y=(not S)and(E>0 and os.time()>=E)end elseif(os.clock()-f)>=120 then f=os.clock()if not y()then Y=true end end if Y then I()return end end end)end;((function()local x="silence_seen.txt"local Q={{v="v312";lines={"MURDER MYSTERY 2 is in the Games tab.";"","    A third card next to German Voice and Blade Ball. It unlocks by","    itself the moment you are in MM2 - the place name is matched on";"    join, so nobody has to type an id.";"","    THIS IS STAGE ONE, and it only DRAWS. Roles come from the game\'s";"    own client round module, coins and traps from tags and names","    already in the map, and every marker lives on your machine.","    Nothing on this page sends anything to the server.";"";"      Nametag ESP \194\183 Role Tags \194\183 Chams \194\183 Box ESP \194\183 Skeleton ESP","      Distance Limit \194\183 Coin ESP \194\183 Trap ESP";"      Murderer Nearby \194\183 Kill Feed","";"    Role detection asks the round module first and falls back to the";"    weapon tags, which covers the gap between a round starting and","    the module filling in - exactly when you want to know who has","    the knife.","","    One loop at 15Hz drives every marker, and it stops dead on its","    first line when nothing is switched on. Coins refresh at 4Hz,";"    traps at 5Hz. This does not repeat the mistake that cost 300ms";"    a tick in the sync poll.";"","    Trap ESP is honest about itself: the open source script it came";"    from marks it UNTESTED, because traps appear too rarely for its";"    author to confirm. It may show nothing.";"";"    Stage two - auto kill, silent aim, instant knife - comes once","    this is confirmed in a real round. Those three fire the game\'s";"    remotes and belong last, not first.",""}};{v="v311";lines={"ONLINE USERS: head shots, and rows that stop being rebuilt.","";"    Every row now carries the player\'s head shot, the way the chat";"    rows do.","","    That was only affordable after fixing what sat underneath it.","    The list destroyed every row and built it again from nothing","    every 4 seconds while the window was open - six instances per";"    row plus a fresh click connection each time. Adding a picture to";"    that would have re-requested every thumbnail on every pass.";"","    Rows are built once and kept. A refresh only writes their text";"    and their target, the head shot is fetched only when the person","    in that row actually changes, and surplus rows are hidden rather";"    than destroyed. The JOIN button is connected once for the life of";"    the row and reads whoever it currently shows.","";"    Scrolling already worked - the list has always been a scrolling","    frame that grows with its contents. Nothing was broken there and","    nothing was changed.";""}},{v="v310",lines={"VCB: a warning under the button that nobody can miss.";"","    Its own card, red edge, bold heading, directly under Activate","    VCB - not styled like the dim hints the rest of the panel uses,","    because a warning that looks like a footnote is not a warning.","";"    It says what the risk is: voice is reviewed after the fact, a","    ban can land days later, and insulting people is the fastest way","    to lose the account the key is tied to.";""}};{v="v309";lines={"EVERY COSTUME ASSET WAS LOADED ONCE PER PLAYER. NOW ONCE, TOTAL.","";"    loadAssetRoot had no cache. The LARP sync dresses every player in","    the server from their slots, so ten people wearing the same";"    Korblox leg meant TEN blocking loads of one identical asset -","    and all of it again after every respawn.";"","    game:GetObjects blocks the client until the asset arrives; this","    file warns about that in two other places already. The loaded","    asset is kept as a template now and each caller gets a copy.";"","    A dead id is remembered as dead. Without that, an unresolvable";"    slot blocked once per player per respawn, forever, only to fail","    again every time.","","    This one needed no measurement: loading the same thing ten times";"    is wrong whatever each load costs.";"";"THE CHAT POLL PACES ITSELF TOO.","","    Same fixed 4 second gap around the same blocking HttpGet that the";"    sync poll had before v306, so it stalled the client every 4","    seconds for as long as the chat tab stayed open. It stretches","    only while the chat is actually being polled - with the window";"    shut there was never a cost to slow down.";""}},{v="v308";lines={"THE GRAPH WAS LYING, AND NOW IT CANNOT.","","    \"min 2\" printed beside \"worst frame 68ms\" is impossible - a";"    quarter-second window at 2 FPS with no long frame in it cannot";"    exist. Both numbers came from RenderStepped, and RenderStepped","    does not fire at all while the client is blocked inside a","    synchronous call. So a blocking load leaves NO long frame behind";"    and stayed invisible to the very figure meant to catch it.","";"    The sampler asks for 0.25s and now measures what it actually","    got. Anything beyond that is time the client spent frozen, and","    it appears in the graph as \"blocked\".";"";"    If \"ours\" is small and \"blocked\" is large, the stall is not one";"    of our timed loops - which is as useful an answer as naming one.","","TWO BLOCKING CALLS ARE TIMED FOR THE FIRST TIME.","","    loadAssetRoot (game:GetObjects) blocks until the asset arrives,";"    and the LARP sync calls it for EVERY player in the server and","    EVERY slot of their costume, again on every respawn. In a busy","    larp server that is dozens of blocking loads, and nothing has";"    ever measured it. It shows up as \"asset load\".";"","    GetCharacterAppearanceAsync shows up as \"avatar fetch\".";""}};{v="v307",lines={"DRAGGING THE PANEL LAGGED. It ran on mouse events, not on frames.";"";"    The shared drag dispatcher hung off InputChanged, which fires at","    the mouse\'s polling rate - 125 to 1000 times a second - while";"    the screen redraws 60 to 240 times. On EVERY event it walked";"    every registered handler and pcall\'d each one, and there is one";"    per slider, colour strip and draggable header: about forty.","";"    So moving the mouse at all cost tens of thousands of pcalls a";"    second, and the handler being dragged wrote the panel\'s Position";"    several times per frame - each write forcing a full layout pass";"    over the whole panel tree, when only the last one of a frame can";"    ever be seen.","","    Only the newest event is kept now and it is dispatched once, on";"    the frame. Nothing is lost: every handler computes from an";"    absolute mouse position rather than accumulating deltas.","";"    Also timed, as \"drag dispatch\", so the graph can confirm it.","","The sync poll\'s JSON unpacking is timed separately from the request.";"    \"http all 85ms\" only ever measured the wire; a big payload is a","    server-side fix and a slow connection is not, so the two had to","    be told apart before anything else is changed.";""}};{v="v306",lines={"FOUND IT. THE STUTTER WAS THE SYNC POLL, AND IT IS MEASURED.","";"    The timer added in v304 answered it:";"","        http all   296.6 ms","","    HttpGet is implemented natively and SYNCHRONOUSLY by the","    executor, so it blocks the whole client - task.spawn does not","    help, because that thread never yields. The sync poll ran on a","    fixed 4 second gap, so the client froze for ~300ms every 4","    seconds: about 7% of all time, in exactly the chunks the graph","    kept reporting as min 1 and worst frame 297ms.","","    IT IS ALSO WHY OTHER PLAYERS LAGGED. A frozen client does not";"    replicate, so everyone else saw you jump and rubber-band - and","    in a server with several Silence users, everybody was freezing","    on their own 4 second cycle.","","    The poll now paces itself by what it actually costs, so it can","    never take more than ~2.5% of your time. A 296ms call earns a";"    ~12s pause; a 20ms call keeps the full 4s responsiveness. No","    slower interval is forced on anyone whose executor is fast.","";"    Two smaller ones are left alone on purpose: the key check runs";"    every 120s, and the chat poll only while the chat is open.",""}};{v="v305",lines={"SPAMMING THE MENU KEY LAGGED. Two stacked tweens, both unguarded.";"";"    Opening or closing started a fresh 0.3s tween on a WHOLE-SCREEN";"    BlurEffect, without cancelling the one already running - and","    that runs on every Visible change of the panel AND of every";"    registered window. Press the key ten times and ten screen-wide","    blur tweens are running at once.";"","    Opening also started a Back-easing tween on the UIScale that";"    wraps the ENTIRE panel. Every frame of it re-measures the whole";"    GUI tree, and those stacked too.","";"    Both now do what _setMinimized has always done: nothing at all";"    if the goal has not changed, and cancel the running tween before","    starting another. The blur is also only switched ON when there","    is something to show - enabling it merely to fade it to zero is","    what left a zero-size blur running after every close.","";"    Both paths are timed, so the graph\'s \"ours:\" line will say";"    whether this was really it.",""}},{v="v304";lines={"THE FPS GRAPH NOW NAMES THE CULPRIT ITSELF.";"","    Two of my theories about the stutter were wrong, and both were";"    built instead of measured. So this version measures.","","    The per-loop timer existed for ten versions and was OFF unless","    you pressed a button in another tab - so the one measurement";"    that would settle this was never taken. It is on by default now";"    and costs two clock reads per site.","","    The graph has a second footer line: the most expensive single";"    thing Silence has done since the last reset, by name. If it";"    shows a small number while the graph shows a 300ms freeze, the";"    freeze is not ours - and that is an answer too.","","    Every one of the four endless HttpGet pollers is timed: all,","    style, chat, key. Many executors implement HttpGet natively and","    SYNCHRONOUSLY, so it blocks the whole client even inside a";"    task.spawn - and one of these runs every 4 seconds forever,";"    which is the shape of a stutter that returns every few seconds.";"    That is a suspicion, not a finding. The graph will say.",""}},{v="v303";lines={"REVERTED: the LPH_NO_VIRTUALIZE change from v300.";"","    The framerate has fallen across the versions since it went in -","    avg 227, then 191, then 149, with the worst frame going from","    72ms to 315ms. That change was made from documentation and was";"    NEVER MEASURED, which is exactly the mistake worth undoing";"    first.","","    There is a real mechanism for it too: an unvirtualised function";"    has to cross the boundary between the VM and real Lua on every";"    call, and it was applied to the __namecall hook, which the";"    engine calls on every remote in the entire game. That crossing","    can cost more than virtualising ever saved.","";"    All six wrappings are gone. The polyfill stays - it costs","    nothing and documents the option for a build where it has";"    actually been measured.","";"    The 30Hz floors from v302 stay. Those remove work rather than";"    moving it, so they cannot be the cause of anything.";""}},{v="v302",lines={"TEXT WAS BEING OUTLINED, LETTER BY LETTER.","";"    A UIStroke on a TextBox, TextButton or TextLabel defaults to";"    Contextual, which draws around every CHARACTER instead of around","    the object. The stroke helper the whole panel uses never set the";"    mode, so every field outlined its own text - visible the moment";"    you typed. Set once in the helper, which fixes every caller; a","    Frame is unaffected, it has no text to outline.","";"    The two SILENCE wordmarks in the intro keep their outline. That","    one is on purpose.";"";"PERFORMANCE: three animation loops were not throttled at all.";"","    The panel\'s animation rate defaults to 240Hz - a shorter step";"    than one frame on any monitor - so every loop that compares","    against it and has no floor runs EVERY FRAME while claiming to","    be stepped. Four of the seven readers already floor at 30Hz,";"    added by hand one at a time. The last three do now too: the";"    panel glow, which rotates every gradient in the interface, and","    two loops beside it.",""}};{v="v301";lines={"KORBLOX: back to what v251 did, because that is the build that","worked.";"";"    v251 - about fifty versions ago - passed FIVE arguments to the";"    mount function. There was no R15 special case at all: the asset";"    was welded on and the hide pass blanked the whole leg. Every","    R15 \'improvement\' added after that (the in-place MeshId swap,";"    the SpecialMesh overlay, the span measurement, the scale","    factors) was built on top of a thing that already worked, and","    broke it - then six versions went into guessing at geometry.","","    Both rigs take the weld path again. The R15 branch is left in","    place but unreachable, so there is something to go back to.";"","    Reading the real three meshes off the wearer\'s account stays as","    the exact path for anyone who OWNS Korblox; it does nothing for";"    an account that does not, which is the case this has to work in.";"","SILENCE CHAT: it reads like a chat now.";"";"    Every message was one TextLabel in Gotham 13, one grey for the","    whole window, and a repeated name on every consecutive line.";"";"    Messages are rows now: head shot, name in bold, the text in";"    GothamMedium 14, the time on the right, and a stripe down the","    left in your colour for your own lines. Consecutive messages","    from one person group instead of repeating the name. The input","    got a focus ring and the send button follows the accent colour";"    instead of a hardcoded red.",""}};{v="v300";lines={"PERFORMANCE: the hot functions no longer run inside Luraph\'s VM.","";"    Your own test settled what the cause is: the SAME code, smooth","    raw and stuttering obfuscated. An obfuscated build runs as";"    bytecode inside a VM written in Lua, so a line that costs one";"    instruction raw can cost forty. Twelve loops in this file were";"    investigated and cleared - it was never a loop.","";"    LPH_NO_VIRTUALIZE leaves a function as real Lua. It did not","    appear in this script even once before now. It is applied to the","    code that runs most often and nowhere else:","","      - both __namecall hooks. These run on EVERY remote call in the";"        whole game, the game\'s own included, not just ours. Easily","        the single hottest function in the file.";"      - the frame counter, which by design has no off-guard.","      - the panel glow and the logo spin.","";"    Everything else already stops on its first line when its window","    is shut, so there is nothing there to win.";"";"    TEST THE OBFUSCATED BUILD BEFORE YOU PUBLISH IT. If Luraph does","    not know the macro, this is the one change to undo.";""}};{v="v299",lines={"KORBLOX: back to the width that was never the problem.","";"    v298 started scaling the mesh sideways from its measurement as";"    well, and the legs came out far too thick. Width sat at 1 from";"    v295 to v297 and was never once wrong - only the height and the","    position were. So the sideways scaling is gone again and the","    measured height stays.";""}};{v="v298",lines={"CONFIG: loading one now really does load ONLY that config.";"";"    Two faults, and together they did exactly what you saw.";"";"    1. A slider or number field was built with a FIXED starting";"    value and had no way to read the setting back. applyConfig put","    the loaded numbers into State correctly and then refreshed every","    row that could refresh - these could not. State was right, the";"    panel still showed your old numbers.";"";"    2. The number box fired its callback on EVERY focus loss, even";"    when you changed nothing. So clicking a field and clicking away";"    wrote the DISPLAYED number back into State - and after a load the","    displayed number was the stale one. The panel overwrote the";"    config with the settings you had set by hand.","","    Rows can now read their own value, so they redraw with everything","    else after a load, and only a real change counts as a change.","","KORBLOX: the mesh height is measured instead of assumed.";"","    The stretch factor is span / the mesh\'s own height, and that","    height was hardcoded as 2 because an R6 leg brick is 1x2x1. If","    the mesh is authored taller, span/2 overshoots and the leg hangs","    down past the foot. It is measured now, width included.",""}},{v="v297",lines={"KORBLOX on R15: the real three meshes, picked up automatically.";"";"    An R15 Korblox leg is THREE meshes - upper leg, lower leg, foot","    - that Roblox builds on its own servers from the one old R6","    part. Every version since v288 stretched that single R6 mesh","    over all three. One rigid object across three bones looks";"    passable standing still and tears off at the knee as soon as","    you walk. That was a wrong SHAPE, not a wrong number.","","    The converted meshes cannot be downloaded, but they can be read","    off any finished avatar already wearing Korblox. If the account","    owns Korblox, its own three meshes are now read and written onto";"    the three segments - it bends at the knee because it IS the leg.";"    Fully automatic: R6 and R15 are detected at mount, and no button","    was added. Answer is cached per user, one web call.","";"    If the account does NOT own Korblox there is nothing to read,";"    and the stretched R6 fallback still runs. That one cannot be","    made exact from a client script - see the note in the file.";""}},{v="v296",lines={"KORBLOX: the leg sat too low. It reaches the hip now.";"";"    The mesh is a whole R6 leg - two studs tall. An R15 leg is","    nearly three. v295 centred it on the real leg without","    stretching it, so it covered the middle and left the hip bare.";"","    It is now stretched in HEIGHT to the measured length of all","    three segments. Width and depth stay untouched - putting stud","    sizes on those is what made the spikes in v294.",""}};{v="v295";lines={"KORBLOX: the SLOT works again. The extra row is gone.","","    There is no second Korblox control any more. Set a slot to","    R.LEG, put the id in, ON, HIDE - the way it always was.";"","    What was broken: on R15 the mount wrote the mesh onto your limb","    and checked it by reading MeshId back. That read is not proof.","    On a build that takes the value but will not redraw the part,","    the check PASSED, so the hide pass blanked the other two leg";"    segments and put nothing in their place - no Korblox and half a";"    leg missing, which is exactly how it was reported six versions","    running. The verify written to catch this could not, because it";"    was asking the wrong question.","";"    Now a separate Part with a SpecialMesh is welded over the leg,","    which renders on every build - the same thing the R6 path has","    always done. It is measured across all three R15 segments, so it","    reaches hip to foot instead of stopping at the knee.";"";"    The thin black spikes were a unit mistake: SpecialMesh.Scale is";"    a multiplier and it had stud sizes written into it.",""}},{v="v294";lines={"THE BLACK BLOCKS WERE A PART WITH NO MESH.";"";"    MeshPart.MeshId assigned at runtime is not honoured on every","    Roblox build - the part silently keeps its box, which is what","    was on your legs. SpecialMesh with MeshType FileMesh accepts an","    id at runtime and always has; the R6 branch of the accessory";"    loader in this same file has been doing it that way for ages.";"","    It also hung off the SHIN. The asset carries a whole R6 leg, so";"    it now welds to the upper leg, is scaled to the measured height","    of all three R15 segments, and hides all three instead of one.",""}},{v="v293";lines={"The Korblox control is now the FIRST row in the Larp Studio\'s";"    costume column. v292 appended it after all twenty-four slots,","    so it sat at the bottom of a long scroll - and the release note","    claimed it was next to Headless, which is not where it was.","","If this panel does not say v293 in its header, the upload did not","    happen and none of the last few fixes are running.",""}},{v="v292";lines={"THE KORBLOX BUTTON HAD NO DOOR.","","    Three versions of work went onto the Avatar tab - the toggle,","    the copy buttons, the asset reader. The Larp Studio DESTROYS","    that tab\'s button when it starts, because its contents were","    adopted into the studio\'s own column. So all of it was running,","    correctly wired, with nothing on screen able to reach it.","","    It was never the technique that failed. It was that there was";"    no way to press it. The control now sits in the Larp Studio";"    under BODY, next to Headless and the Korblox slot.",""}},{v="v291";lines={"KORBLOX NEEDS NO SOURCE ANY MORE. v290 refused to switch on until","    you had copied the leg off another player - which reads as";"    broken when nobody in your server wears it. The mesh was in the";"    asset all along: it loads as a CharacterMesh and that carries a";"    real MeshId. v288 read the same number and then wrote it ONTO","    the limb, which the engine accepts and draws as nothing. It is","    built into its own part and welded on now.";"","PIANO: the sharps on the number row were being thrown away.";"    VirtualPiano writes them as symbols - 5 becomes %, 9 becomes (,","    4 becomes $ - and the parser kept only letters and digits. Every";"    sheet pasted from the internet lost notes, silently, and played";"    on sounding wrong with no error anywhere.";"","Ten more songs, led by RUSH E, taken verbatim from its published","    sheet. The rest are public-domain melodies written out from the","    keyboard map rather than half-remembered.";""}};{v="v290",lines={"KORBLOX, DONE THE WAY IT ACTUALLY WORKS.  Under Avatar > KORBLOX.","","    Four rebuilds failed because they all tried to turn your LIMB";"    into Korblox. There is no R15 Korblox asset to put on it, so","    that could never work - Roblox converts the old R6 part on its";"    own servers and the result is not downloadable.";"","    It IS readable though: anyone on R15 wearing Korblox has the";"    finished leg welded to their bones right now. So this copies the";"    mesh straight off them - from someone in your server, or from a";"    username - keeps it on disk, and welds it onto your own leg with","    the real one hidden behind it. Nothing is hardcoded, so no id in";"    here can ever be the wrong one.",""}};{v="v289",lines={"WHY KORBLOX NEVER WORKED ON R15, ESTABLISHED RATHER THAN GUESSED:";"    bundle 192 contains only LEGACY R6 ASSETS. There is no R15";"    Korblox asset anywhere - Roblox\'s own avatar backend converts","    the R6 part into the three R15 segments when you wear it, and","    that conversion is not something a client can download.";"";"NEW, under Avatar: \"Why is Korblox not showing?\". It asks Roblox to";"    perform that conversion and, if the call goes through, writes";"    the converted leg meshes straight onto your legs - so it is the";"    fix when it works and an honest answer when it does not.";"";"The Doctor now prints YOUR OWN mounts, not only other players\'.","    The one diagnostic for a missing Korblox was silent about the","    only case anybody opens it for.";""}},{v="v288",lines={"KORBLOX SHOWED FOR NOBODY ON R15, WHICH IS EVERY MODERN AVATAR.";"    A body-part asset loads as a CharacterMesh, and a CharacterMesh","    only renders on R6. It was cloned in and accepted as a success","    for every rig, so the R15 mesh swap was never even reached.";"    On R15 the CharacterMesh is now read for its mesh and texture","    ids and swapped onto the limb in place.";"","A failed mount no longer hides your limb. If the asset never";"    arrived, the leg used to be blanked with nothing put in its","    place - indistinguishable from \"Korblox is invisible\". The","    other-players path already guarded this; your own body did not.";""}},{v="v287";lines={"\"worst frame\" is now printed in milliseconds. It used to be stored";"    as the framerate it corresponds to, which rounds 700ms, 1000ms","    and 2000ms all to 1 - so two builds half a second apart per","    freeze printed the same number, and comparing them was useless.";"","The load freeze no longer poisons the statistic. Injection blocks for";"    about a second building the interface; recorded, that one frame";"    owned the worst-frame number for the whole window.";"","The graph said 60s and showed 30s. Its sampler was halved to react to","    stutters and the label was never pulled along.";""}},{v="v286",lines={"The FPS graph was printing two different timescales side by side.";"    min/avg/max covered the whole minute, \"worst frame\" only the last","    quarter second - so \"min 47 / worst frame 91\" read as impossible.","    Worst frame now spans the same window, and shows the ms too.","","The loop measurement is now a toggle instead of a 5-second sample.","    A stutter that happens once a minute gets missed by a 5s window,";"    and the button then reports \"nothing found\" - a false all-clear.";"";"The header labels its ping as ping. It was a bare \"26 ms\" next to";"    the framerate, which reads like a frame time.";""}};{v="v285",lines={"NEW, under FPS Boost: \"Which Silence loop is costing me frames?\"","    It measures for five seconds and names the worst single frame of","    each of our own loops. Counting objects only ever answered";"    whether the PLACE is heavy; this answers whether SILENCE is.";"    If it reports nothing, the stutter is not ours - and that is an";"    answer too.";"","The overhead-tag loop had no off-switch at all: it ran on every";"    frame, before rendering, even with no tags in the server.";""}};{v="v284",lines={"STUTTER: four loops that were supposed to run at 20-30Hz were in fact","    running on EVERY frame. Their throttle compared against the UI";"    animation rate, which defaults to 240 - a shorter interval than","    one frame - so the test could never be true. The worst of them";"    walked every Silence tag in the server and read the camera, every","    single frame, which is why it showed up most when turning around.";"    Also affected: tag effects, the voice overlay and the radar.";"";"The FPS counter now reacts in a quarter second instead of a half,";"    and the graph prints the WORST SINGLE FRAME of that window - a";"    hitch is invisible in an average and obvious in that number.",""}};{v="v283",lines={"FIXED: Korblox could vanish completely after v281. Replacing the leg";"    mesh in place is not allowed on every Roblox build, and that","    refusal was silent - the script carried on as if the swap had","    worked and hid the rest of the leg around a limb that had never","    changed. It now checks whether the swap actually took, and welds";"    the old way when the engine says no.","FIXED: switching a Korblox slot back off left the leg swapped for the","    rest of the session - the original mesh is restored now.",""}},{v="v282",lines={"FIXED: overhead tags falling apart at a distance. The card shrinks";"    with range, but everything inside it - the badge, the padding,";"    the text - was sized in fixed pixels, so from far away the badge";"    and the padding filled the whole card and the name was cut down","    to \"SILE...\". The contents scale with the card now, so a tag";"    looks the same at any range, only smaller.";""}};{v="v281",lines={"FIXED: Korblox in LARP Studio. Two separate faults.","    On your OWN character the in-place mesh swap was never reached,";"    so the leg was welded on as a loose segment instead of replacing";"    the limb.";"    And on an R15 rig a leg is THREE parts while a slot holds one";"    asset - so the thigh turned into Korblox while the shin and the","    foot kept their own mesh and stayed visible. Everything except";"    the swapped part is hidden now, on your body and on everyone","    else\'s.",""}};{v="v280",lines={"A full audit of the script found 221 issues; the 60 most serious were";"    independently double-checked and 55 of those held up. Fixed here:";"","CRASH: pressing LEARN or LOCAL UNLOCK in Blade Ball broke EVERY";"    remote call in the game for the rest of the session.";"KEYS: a dropped connection deleted your remembered key. It only";"    deletes now when the server actually rejects it.","KEYS: with no key you could get stuck on a black screen with no way","    back to the game - there is a way out now.","SAVING: deleting or renaming a config broke that game\'s auto-load;";"    changing the auto-load deleted that game\'s startup commands;";"    saved config+tag pairs never survived a restart. All fixed.","ESP Max Distance was reset to 350 on every config load.";"UNLOAD left running: trigger rules, the whole Sky tab, FPS Boost,";"    hidden players, the watchlist and the anti-VC-ban module.";"Lighting could never be restored once Fullbright had been switched","    on twice, and Disco OFF overwrote it with an invented grey.";"Aimbot stayed locked on corpses, team mates and people behind walls.";"Anti-Fling cancelled your own Fly and any high Walk Speed.";"Carry broke permanently if the target left, or after your respawn.","Infinite Jump launched you in the direction you last walked.","Stolen accessories were never removed, and every steal after the","    first silently wore none.","The colour picker opened BEHIND the Sky editor - all 10 sky colour";"    rows were unusable.";"The four weather buttons emitted invisible particles.";"Opening the panel used to drop an Atmosphere and Clouds into the","    game before you touched anything.","Anim pack VERIFY ALL always reported 0 of 7.";"Per-player MUTE could mute but never unmute.";"Hotkeys bound to a mouse button never fired.","Emote and anim-pack caches were written but never read back on some";"    executors.","A web hiccup could permanently mark a pass OWNER as not owning it.";"Streamer mode renumbered everyone whenever somebody left, and froze","    the game\'s own overhead text at its first value.";"PERFORMANCE: removed per-frame allocations from the ESP loop, the";"    voice overlay, the nametag masker and AutoFish, and stopped the";"    nametag keeper from walking Silence\'s own UI every second.";""}};{v="v279";lines={"FIXED, properly this time: Infinite Jump stopping you in mid-air.","    v278 added a 0.14s delay, and Roblox\'s jump state lasts about","    0.2s - so it still re-entered the state before it had ended, and","    that state grants no new lift and runs no air control. It now","    waits for the humanoid to actually reach free-fall.";"You also keep your forward speed now. Roblox drives movement from","    the key you hold rather than from momentum, so letting go used";"    to stop you dead in the air - your take-off speed is carried and","    steered while you hold jump.","","FIXED: emote favourites were being ERASED, not forgotten. A saved";"    config carries an empty favourites list when you had none, and";"    loading it wiped yours and wrote the empty list over the file.","    A config can only ADD favourites now, never remove one.";"FIXED: favourites were never read back on executors without isfile,";"    although saving them only ever needed writefile.";"The heart and the eye in the emote list are redrawn - better","    proportions, a pupil that finally has a colour, and hover.";"","First inject now opens the DASHBOARD instead of a small key box.","    Enter your key there, it is checked on the spot, and START","    SILENCE appears once it passes. Tick \"remember\" and the next";"    inject goes straight to START.","";"FIXED: carry and every stick mode shaking when the target ran fast.";"    Three thresholds in the sync code were fixed distances while the";"    movement they measure scales with speed, so ordinary sprinting";"    was read as an error and answered with freezes and hard snaps.";"    They scale with the target\'s speed now.","","Radar / minimap - its own round window under the HUD, drag it anywhere";"FPS / ping graph - the last 60 seconds, so a stutter becomes a shape","Hide other players (FPS Boost) - the heaviest thing in a full server";"Crosshair (Visual) - length, gap, thickness and colour","Watchlist - name the people you want to hear about the moment they join","Item alert - Item ESP shows them, this one tells you";"Share code - your whole setup as one line you can paste to a friend";"Publish setup - park it on the sync server and let other Silence","    users pull it straight from the online list","Compare (Config) - what differs between a saved profile and right now";"Scheduler (Misc) - \"20 > hop\" and it happens in twenty minutes";"Game notes (Misc) - a notepad tied to this place id";"Update check (Misc) - asks GitHub whether a newer build is out";"Unlock camera zoom - for games that pin you into first person";"Doctor (Logs) - says which features your executor cannot run, and why","Timeline (Logs) - chat, joins and notifications on one time axis","Ghost replay (Misc) - the last 60 seconds of where you stood, played back";"Keybind sheet - hold Right Alt to see every bind you have","";"REMOVED: the Discord webhook. It needed the executor to expose","    request() for a POST, and too many of them simply do not.";"REMOVED: Model ESP. Dressing everyone in a bundle id was fiddly to";"    use and the result was never worth the bundle hunting.","","FIXED: binding a profile to a game wrote a \'places\' list the loader","    did not know about, and the NEXT launch crashed the whole profile";"    load on it - configs, tags, skies and pairs all gone at once.";"FIXED: trigger rules were saved as the word \'true\' and silently came","    back empty on every single launch. They persist properly now."}}}local function Y()return type(writefile)=="function"and type(readfile)=="function"end local function E()if not Y()then return nil end if type(isfile)=="function"then local Q,Y=pcall(function()return isfile(x)end)if Q and not Y then return""end end local Q,E=pcall(function()return readfile(x)end)if not Q or type(E)~="string"then return""end return(E:gsub("%s+$",""))end local function r(Q)if not Y()then return end pcall(function()writefile(x,tostring(Q))end)end local S local function k()if S then return end S=Instance.new("Frame",TB)S.Name="SilenceWhatsNew"S.AnchorPoint=Vector2.new(.5,.5)S.Size=UDim2.new(0,480,0,420)S.Position=UDim2.new(.5,0,.5,0)S.BackgroundColor3=Z.bg S.BorderSizePixel=0 S.ZIndex=470 S.Visible=false S.Acti